import{c as e,Q as l,j as i,m as t}from"./chunks/framework.BPKcPtvA.js";const q=JSON.parse('{"title":"Hyperliquid 资产恢复机器人文档（HackMD 中文合并版） | Hyperliquid Recovery Bot","description":"如果你在 Hyperliquid 看到这段报错：\\"Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.\\" 这份中文指南会带你完成地址检测、资产恢复、费用查看、状态说明和 FAQ。","frontmatter":{"title":"Hyperliquid 资产恢复机器人文档（HackMD 中文合并版）","tags":["Hyperliquid","资产恢复","Telegram Bot","Arbitrum","DeFi"],"description":"如果你在 Hyperliquid 看到这段报错：\\"Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.\\" 这份中文指南会带你完成地址检测、资产恢复、费用查看、状态说明和 FAQ。","head":[["link",{"rel":"canonical","href":"https://hyperliquidrecoverybot.github.io/hackmd.zh"}],["meta",{"name":"keywords","content":"Hyperliquid, Recovery Bot, flagged address, Hyperliquid 资产恢复机器人文档（HackMD 中文合并版）"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"Hyperliquid 资产恢复机器人文档（HackMD 中文合并版） | Hyperliquid Recovery Bot"}],["meta",{"property":"og:description","content":"如果你在 Hyperliquid 看到这段报错：\\"Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.\\" 这份中文指南会带你完成地址检测、资产恢复、费用查看、状态说明和 FAQ。"}],["meta",{"property":"og:url","content":"https://hyperliquidrecoverybot.github.io/hackmd.zh"}],["meta",{"name":"twitter:card","content":"summary"}],["meta",{"name":"twitter:title","content":"Hyperliquid 资产恢复机器人文档（HackMD 中文合并版） | Hyperliquid Recovery Bot"}],["meta",{"name":"twitter:description","content":"如果你在 Hyperliquid 看到这段报错：\\"Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.\\" 这份中文指南会带你完成地址检测、资产恢复、费用查看、状态说明和 FAQ。"}]]},"headers":[],"relativePath":"hackmd.zh.md","filePath":"hackmd.zh.md","lastUpdated":null}'),r={name:"hackmd.zh.md"};function o(d,a,h,n,s,c){return l(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="hyperliquid-recovery-bot-文档-hackmd-中文合并版" tabindex="-1">Hyperliquid Recovery Bot 文档（HackMD 中文合并版） <a class="header-anchor" href="#hyperliquid-recovery-bot-文档-hackmd-中文合并版" aria-label="Permalink to &quot;Hyperliquid Recovery Bot 文档（HackMD 中文合并版）&quot;">​</a></h1><blockquote><p>本文件为 HackMD 单页阅读优化版，仅做内容聚合，不替代原始 GitBook 多文件结构。</p></blockquote><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ul><li><a href="#项目概述">项目概述</a></li><li><a href="#快速开始">快速开始</a></li><li><a href="#资产恢复">资产恢复</a></li><li><a href="#费用与到账">费用与到账</a></li><li><a href="#执行状态说明">执行状态说明</a></li><li><a href="#安全与隐私">安全与隐私</a></li><li><a href="#地址检测">地址检测</a></li><li><a href="#机器人使用">机器人使用</a></li><li><a href="#功能特性">功能特性</a></li><li><a href="#术语表">术语表</a></li><li><a href="#文档更新日志">文档更新日志</a></li><li><a href="#常见问题faq">常见问题（FAQ）</a></li></ul><hr><h2 id="项目概述" tabindex="-1">项目概述 <a class="header-anchor" href="#项目概述" aria-label="Permalink to &quot;项目概述&quot;">​</a></h2><h1 id="hyperliquid-资产恢复机器人-风险地址解决方案" tabindex="-1">Hyperliquid 资产恢复机器人：风险地址解决方案 <a class="header-anchor" href="#hyperliquid-资产恢复机器人-风险地址解决方案" aria-label="Permalink to &quot;Hyperliquid 资产恢复机器人：风险地址解决方案&quot;">​</a></h1><p>Hyperliquid Recovery Bot 专为因高风险被标记而受限的地址提供资产恢复引导服务。</p><p><img src="https://img.shields.io/badge/Hyperliquid-Recovery%20Bot-blue" alt="Hyperliquid Recovery Bot"><img src="https://img.shields.io/badge/version-2.7.0-green" alt="Version"><img src="https://img.shields.io/badge/license-MIT-blue" alt="License"><img src="https://img.shields.io/badge/last%20updated-2026--03-brightgreen" alt="Last Updated"></p><blockquote><p>💡 <strong>急需资金救援？</strong> 直接从下方“建议阅读顺序”开始。</p></blockquote><h2 id="产品定位" tabindex="-1">产品定位 <a class="header-anchor" href="#产品定位" aria-label="Permalink to &quot;产品定位&quot;">​</a></h2><p>该工具是面向“地址可连接但因高风险限制无法操作资产”场景的 Telegram 资产恢复与提取助手。</p><p>该场景下，Hyperliquid 前端常见拦截提示为：</p><blockquote><p>Action blocked: Address flagged for suspicious activity. Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.</p></blockquote><p>该场景下，前端通常会出现红色风险提示层，且常规的资产操作按钮通常会被受限或禁用。机器人会帮助您判断哪些资产现在可以处理、按步骤引导恢复，并将资金返回到源地址对应的 Arbitrum 地址。</p><h2 id="适用人群" tabindex="-1">适用人群 <a class="header-anchor" href="#适用人群" aria-label="Permalink to &quot;适用人群&quot;">​</a></h2><ul><li>您可以控制该地址的私钥或助记词，但由于风控判定在前端受限。</li><li>您希望按照引导完成恢复，而不是自己手动处理多个步骤。</li><li>您需要在执行恢复提现之前看到明确的链上费用和预估到账。</li></ul><h2 id="您将获得" tabindex="-1">您将获得 <a class="header-anchor" href="#您将获得" aria-label="Permalink to &quot;您将获得&quot;">​</a></h2><ul><li>覆盖现货、合约、金库、质押资产的完整检测。</li><li>带实时进度的分阶段恢复流程。</li><li>统一费用展示：<code>Service Fee</code>、<code>Withdrawal Fees</code>、<code>Total Cost</code>、<code>You Will Receive</code>。</li><li>可追溯链上结果（交易哈希）。</li></ul><h2 id="恢复范围" tabindex="-1">恢复范围 <a class="header-anchor" href="#恢复范围" aria-label="Permalink to &quot;恢复范围&quot;">​</a></h2><ul><li><strong>现货资产</strong>：非 USDC 资产转换为 USDC。</li><li><strong>永续持仓</strong>：符合条件的仓位会在恢复过程中处理。</li><li><strong>金库资产</strong>：本次能直接提取的部分会优先处理，暂时不可提的部分留待后续再次执行。</li><li><strong>质押资产</strong>：机器人会按当前所处阶段逐步处理，并在需要等待时告诉您何时再次运行。</li></ul><h2 id="安全原则" tabindex="-1">安全原则 <a class="header-anchor" href="#安全原则" aria-label="Permalink to &quot;安全原则&quot;">​</a></h2><ul><li>仅使用官方机器人入口。</li><li>除机器人内正式恢复流程外，不要向任何个人、群组、表单或网站提供私钥或助记词。</li><li>请以交易哈希和链上结果作为最终核对依据。</li></ul><h2 id="费用原则" tabindex="-1">费用原则 <a class="header-anchor" href="#费用原则" aria-label="Permalink to &quot;费用原则&quot;">​</a></h2><ul><li><strong>Service Fee</strong>：恢复金额的 0.5%，最低 1 USDC。</li><li><strong>Withdrawal Fees</strong>：共 2 USDC（两次提现，每次 1 USDC）。</li><li><strong>Total Cost</strong>：Service Fee + Withdrawal Fees。</li><li><strong>You Will Receive</strong>：预估可恢复价值 - Total Cost。</li></ul><h2 id="建议阅读顺序" tabindex="-1">建议阅读顺序 <a class="header-anchor" href="#建议阅读顺序" aria-label="Permalink to &quot;建议阅读顺序&quot;">​</a></h2><ol><li>访问机器人：<a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li>阅读 <a href="#快速开始">快速开始</a></li><li>阅读 <a href="#资产恢复">资产恢复</a></li><li>阅读 <a href="#费用与到账">费用与到账</a></li><li>阅读 <a href="#安全与隐私">安全与隐私</a></li></ol><h2 id="操作提示" tabindex="-1">操作提示 <a class="header-anchor" href="#操作提示" aria-label="Permalink to &quot;操作提示&quot;">​</a></h2><ul><li>最终提现默认到源地址对应的 Arbitrum 地址（同一地址）。</li><li>提现发起后资金不会立刻到达 Arbitrum，到账时间取决于 Hyperliquid 处理速度，可能需要几分钟到十几分钟。</li><li>结果页可能显示：<code>completed</code>、<code>partial</code>、<code>waiting_to_rerun</code>、<code>failed</code>。</li><li>若出现 <code>partial</code>，表示已有一部分资产处理完成，但可能还需要继续处理剩余部分。</li><li>若出现 <code>waiting_to_rerun</code>，表示现在还需要等待，到了提示时间再回来继续即可。</li><li>若当前还没有资产能被处理，结果不会显示为 <code>completed</code>。</li></ul><h2 id="获取帮助" tabindex="-1">获取帮助 <a class="header-anchor" href="#获取帮助" aria-label="Permalink to &quot;获取帮助&quot;">​</a></h2><ul><li>查看 <a href="#常见问题faq">常见问题（FAQ）</a></li><li>查看 <a href="#执行状态说明">执行状态说明</a></li><li>通过机器人内反馈联系支持</li></ul><hr><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><h1 id="快速开始-1" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始-1" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>本页提供一条 5 分钟可执行路径，帮助您从零开始完成首轮检测与恢复。</p><p>适用场景：地址可在 Hyperliquid 前端连接，但会出现红色高风险提示层，且大部分资产操作按钮通常会受限或禁用。</p><h2 id="_1-进入机器人" tabindex="-1">1) 进入机器人 <a class="header-anchor" href="#_1-进入机器人" aria-label="Permalink to &quot;1) 进入机器人&quot;">​</a></h2><ul><li>官方入口：<a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li>或在 Telegram 搜索：<a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li>发送 <code>/start</code> 初始化会话</li></ul><h2 id="_2-先做地址检测-推荐" tabindex="-1">2) 先做地址检测（推荐） <a class="header-anchor" href="#_2-先做地址检测-推荐" aria-label="Permalink to &quot;2) 先做地址检测（推荐）&quot;">​</a></h2><ol><li>点击 <code>🔍 地址检测</code> 或发送 <code>/detect</code></li><li>输入地址（<code>0x</code> 开头，42 字符）</li><li>等待机器人扫描现货、合约、金库和质押相关资产</li><li>查看总价值、是否有等待/锁定资产，以及当前可处理的部分</li></ol><h2 id="_3-启动资产恢复" tabindex="-1">3) 启动资产恢复 <a class="header-anchor" href="#_3-启动资产恢复" aria-label="Permalink to &quot;3) 启动资产恢复&quot;">​</a></h2><ol><li>点击 <code>🛠️ 资产恢复</code> 或发送 <code>/recovery</code></li><li>输入源地址（被标记的待恢复地址）</li><li>输入私钥或助记词（仅用于本次签名）</li><li>确认恢复计划和费用明细后执行</li></ol><p>说明：如果部分资产暂时还不能处理，预览页会直接提示需要等待，而不会误显示为可以立刻处理。</p><h2 id="_4-你会看到什么" tabindex="-1">4) 你会看到什么 <a class="header-anchor" href="#_4-你会看到什么" aria-label="Permalink to &quot;4) 你会看到什么&quot;">​</a></h2><ul><li>分阶段的恢复进度展示</li><li>每一步的状态提示，告诉您是已完成、需等待、已跳过还是失败</li><li>结果页会告诉您本轮是已完成、部分完成、需要稍后再试，还是执行失败</li><li>执行摘要：恢复金额、实际费用、交易哈希</li></ul><h2 id="_5-费用口径" tabindex="-1">5) 费用口径 <a class="header-anchor" href="#_5-费用口径" aria-label="Permalink to &quot;5) 费用口径&quot;">​</a></h2><ul><li><code>Service Fee</code>：0.5%，最低 1 USDC</li><li><code>Withdrawal Fees</code>：2 USDC（两次提现）</li><li><code>Total Cost</code>：Service Fee + Withdrawal Fees</li><li><code>You Will Receive</code>：预估可恢复价值 - Total Cost</li></ul><p>详细请看 <a href="#费用与到账">费用与到账</a>。</p><h2 id="_6-特殊情况" tabindex="-1">6) 特殊情况 <a class="header-anchor" href="#_6-特殊情况" aria-label="Permalink to &quot;6) 特殊情况&quot;">​</a></h2><ul><li><strong>质押资产</strong>：可能涉及等待期，机器人会给出再次执行时间。</li><li><strong>金库锁定</strong>：暂时不可提的资产会被标记为等待，解锁后再次执行即可。</li><li><strong>小额余额</strong>：受最小提现限制影响，部分步骤可能不生成。</li><li><strong>到账延迟</strong>：提现发起后资金不会立刻到达 Arbitrum，到账时间取决于 Hyperliquid 的处理速度，通常可能需要几分钟到十几分钟。</li></ul><h2 id="_7-安全检查清单" tabindex="-1">7) 安全检查清单 <a class="header-anchor" href="#_7-安全检查清单" aria-label="Permalink to &quot;7) 安全检查清单&quot;">​</a></h2><ol><li>仅使用官方机器人入口</li><li>仅在可信设备与网络操作</li><li>确认源地址在 Arbitrum 网络可正常接收资产</li><li>不截图和传播私钥/助记词</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>查看 <a href="#资产恢复">资产恢复</a></li><li>查看 <a href="#执行状态说明">执行状态说明</a></li><li>查看 <a href="#常见问题faq">常见问题（FAQ）</a></li></ul><hr><h2 id="资产恢复" tabindex="-1">资产恢复 <a class="header-anchor" href="#资产恢复" aria-label="Permalink to &quot;资产恢复&quot;">​</a></h2><h1 id="hyperliquid-资金急救-风险地址受困资产提取执行流" tabindex="-1">Hyperliquid 资金急救：风险地址受困资产提取执行流 <a class="header-anchor" href="#hyperliquid-资金急救-风险地址受困资产提取执行流" aria-label="Permalink to &quot;Hyperliquid 资金急救：风险地址受困资产提取执行流&quot;">​</a></h1><p>本资产恢复核心流程专门针对被风控标记的 Hyperliquid 风险地址，提供将现货、合约及质押等各类受困资产安全转换为 USDC 并发起恢复提现到原 Arbitrum 钱包的自动化方案。</p><h2 id="执行前输入" tabindex="-1">执行前输入 <a class="header-anchor" href="#执行前输入" aria-label="Permalink to &quot;执行前输入&quot;">​</a></h2><p>您需要准备以下信息：</p><ol><li>源地址（待恢复地址）</li><li>私钥或助记词（仅用于签名）</li></ol><h2 id="标准-7-步流程" tabindex="-1">标准 7 步流程 <a class="header-anchor" href="#标准-7-步流程" aria-label="Permalink to &quot;标准 7 步流程&quot;">​</a></h2><p>机器人会根据实际资产自动生成并执行步骤；不满足条件的步骤会被跳过。</p><ol><li>检查账户状态</li><li>转换现货资产（非 USDC -&gt; USDC）</li><li>按需处理永续仓位</li><li>提取当前可提的金库资产</li><li>处理质押与可提余额</li><li>收取服务费</li><li>完成最终提现</li></ol><h2 id="步骤行为说明" tabindex="-1">步骤行为说明 <a class="header-anchor" href="#步骤行为说明" aria-label="Permalink to &quot;步骤行为说明&quot;">​</a></h2><h3 id="_1-账户准备、现货与永续" tabindex="-1">1) 账户准备、现货与永续 <a class="header-anchor" href="#_1-账户准备、现货与永续" aria-label="Permalink to &quot;1) 账户准备、现货与永续&quot;">​</a></h3><ul><li>账户状态：若恢复前需要先完成账户调整，机器人会优先处理。</li><li>现货：卖出非 USDC 资产，优先完成归集。</li><li>永续：按可执行条件关闭或处理相关仓位，为后续恢复做准备。</li></ul><h3 id="_2-金库" tabindex="-1">2) 金库 <a class="header-anchor" href="#_2-金库" aria-label="Permalink to &quot;2) 金库&quot;">​</a></h3><ul><li>当前可提资产：正常提取。</li><li>锁定资产或当前无可提额度资产：在预览与结果中标记为 waiting/locked，等待解锁或额度恢复后重试。</li></ul><h3 id="_3-质押-重点" tabindex="-1">3) 质押（重点） <a class="header-anchor" href="#_3-质押-重点" aria-label="Permalink to &quot;3) 质押（重点）&quot;">​</a></h3><p>机器人会区分三类状态：已解除质押可处理、仍在质押中、以及等待提现完成。</p><p>可能出现两种路径：</p><ul><li><strong>较快路径（2 次）</strong>：若部分质押余额已进入下一处理阶段，第一次运行可先提取其中一部分，剩余部分在等待期结束后继续处理。</li><li><strong>标准路径（3 次）</strong>：若余额仍处于完整质押状态，通常需要先解除质押，再在后续时间窗口完成提现。</li></ul><p>机器人会在结果中明确下一次建议执行时间。</p><h2 id="费用与到账" tabindex="-1">费用与到账 <a class="header-anchor" href="#费用与到账" aria-label="Permalink to &quot;费用与到账&quot;">​</a></h2><ul><li><code>Service Fee</code>：0.5%，最低 1 USDC</li><li><code>Withdrawal Fees</code>：2 USDC</li><li><code>Total Cost</code>：Service Fee + Withdrawal Fees</li><li><code>You Will Receive</code>：预估可恢复价值 - Total Cost</li></ul><p>详见 <a href="#费用与到账">费用与到账</a>。</p><h2 id="执行结果阅读" tabindex="-1">执行结果阅读 <a class="header-anchor" href="#执行结果阅读" aria-label="Permalink to &quot;执行结果阅读&quot;">​</a></h2><p>您会看到每一步状态和最终摘要：</p><ul><li>Recovered Amount（恢复结果金额）</li><li>Actual Fees（实际费用）</li><li>交易哈希（可链上核验）</li></ul><p>说明：提现发起后到 Arbitrum 的到账是异步过程，受 Hyperliquid 处理速度影响，通常可能需要几分钟到十几分钟。</p><p>状态定义见 <a href="#执行状态说明">执行状态说明</a>。</p><p>如果结果页提示仍需等待，请按建议时间再次运行。</p><h2 id="失败与重试策略" tabindex="-1">失败与重试策略 <a class="header-anchor" href="#失败与重试策略" aria-label="Permalink to &quot;失败与重试策略&quot;">​</a></h2><ul><li>网络短时异常：可直接重试。</li><li>锁定/等待状态：按提示时间再次运行。</li><li>输入错误（地址或私钥不匹配）：修正后重试。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ol><li>先执行一次地址检测，确认资产结构。</li><li>无需填写目标地址，资产将默认提现到源地址对应的 Arbitrum 地址。</li><li>对包含质押或金库资产的地址，设置提醒并按时间窗口重跑。</li></ol><hr><h2 id="费用与到账-1" tabindex="-1">费用与到账 <a class="header-anchor" href="#费用与到账-1" aria-label="Permalink to &quot;费用与到账&quot;">​</a></h2><h1 id="费用与到账-2" tabindex="-1">费用与到账 <a class="header-anchor" href="#费用与到账-2" aria-label="Permalink to &quot;费用与到账&quot;">​</a></h1><p>本文说明您可能支付的费用、费用如何计算，以及最终预计会收到多少资产。</p><h2 id="费用术语" tabindex="-1">费用术语 <a class="header-anchor" href="#费用术语" aria-label="Permalink to &quot;费用术语&quot;">​</a></h2><ul><li><code>Service Fee</code>：服务费，按恢复金额的 0.5% 计算，最低 1 USDC。</li><li><code>Withdrawal Fees</code>：提现手续费，Hyperliquid 每次提现固定 1 USDC。</li><li><code>Total Cost</code>：总成本，等于 Service Fee + Withdrawal Fees。</li><li><code>You Will Receive</code>：用户预计到账，等于预估可恢复价值 - Total Cost。</li></ul><p>其中“预估可恢复价值”指本次实际能够处理的资产价值；仍处于锁定或等待状态的资产，暂时不会计入。</p><h2 id="费用结构" tabindex="-1">费用结构 <a class="header-anchor" href="#费用结构" aria-label="Permalink to &quot;费用结构&quot;">​</a></h2><p>恢复通常包含两次提现，因此 <code>Withdrawal Fees = 2 USDC</code>：</p><ol><li>服务费提现：1 USDC 平台手续费</li><li>最终提现：1 USDC 平台手续费</li></ol><h2 id="计算公式" tabindex="-1">计算公式 <a class="header-anchor" href="#计算公式" aria-label="Permalink to &quot;计算公式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Service Fee = max(预估可恢复价值 × 0.5%, 1 USDC)</span></span>
<span class="line"><span>Withdrawal Fees = 2 USDC</span></span>
<span class="line"><span>Total Cost = Service Fee + Withdrawal Fees</span></span>
<span class="line"><span>You Will Receive = 预估可恢复价值 - Total Cost</span></span></code></pre></div><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>预估可恢复价值</th><th>Service Fee</th><th>Withdrawal Fees</th><th>Total Cost</th><th>You Will Receive</th></tr></thead><tbody><tr><td>100 USDC</td><td>1.00</td><td>2.00</td><td>3.00</td><td>97.00</td></tr><tr><td>1,000 USDC</td><td>5.00</td><td>2.00</td><td>7.00</td><td>993.00</td></tr><tr><td>10,000 USDC</td><td>50.00</td><td>2.00</td><td>52.00</td><td>9,948.00</td></tr></tbody></table><h2 id="结果页会如何显示" tabindex="-1">结果页会如何显示 <a class="header-anchor" href="#结果页会如何显示" aria-label="Permalink to &quot;结果页会如何显示&quot;">​</a></h2><ul><li>执行前：显示预估值（Estimated）。</li><li>执行后：显示实际值（Actual）。</li><li>预估与实际之间可能会因为执行期间价格变化而出现轻微差异。</li></ul><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>地址检测永久免费。</li><li>若本次没有成功处理任何资产，就不会产生不必要的服务费扣除。</li><li>最终提现仍需满足 Hyperliquid 的最小提现要求（常见阈值 1.01 USDC）。</li><li>提现发起后，到 Arbitrum 的到账时间取决于 Hyperliquid 的处理速度，可能需要几分钟到十几分钟。</li></ul><hr><h2 id="执行状态说明" tabindex="-1">执行状态说明 <a class="header-anchor" href="#执行状态说明" aria-label="Permalink to &quot;执行状态说明&quot;">​</a></h2><h1 id="执行状态说明-1" tabindex="-1">执行状态说明 <a class="header-anchor" href="#执行状态说明-1" aria-label="Permalink to &quot;执行状态说明&quot;">​</a></h1><p>恢复系统分为两层状态：步骤级状态用于展示每一步执行情况，任务级终态用于告诉您整次恢复应如何理解和下一步怎么做。</p><h2 id="任务级终态" tabindex="-1">任务级终态 <a class="header-anchor" href="#任务级终态" aria-label="Permalink to &quot;任务级终态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>终态</th><th>含义</th><th>建议动作</th></tr></thead><tbody><tr><td>completed</td><td>本轮已有实际推进或实际恢复金额，且当前无需立即再次运行</td><td>无需立即再次运行</td></tr><tr><td>partial</td><td>本轮仅完成部分恢复，或本轮没有实际恢复金额但仍存在待处理资产/等待状态</td><td>查看摘要和备注，按需继续处理</td></tr><tr><td>waiting_to_rerun</td><td>本轮已推进成功，但协议等待期/锁定期尚未结束</td><td>到期后再次运行恢复</td></tr><tr><td>failed</td><td>本轮执行被致命错误中断</td><td>先处理错误原因再重试</td></tr></tbody></table><h2 id="步骤级状态" tabindex="-1">步骤级状态 <a class="header-anchor" href="#步骤级状态" aria-label="Permalink to &quot;步骤级状态&quot;">​</a></h2><h2 id="状态总览" tabindex="-1">状态总览 <a class="header-anchor" href="#状态总览" aria-label="Permalink to &quot;状态总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>图标</th><th>含义</th><th>建议动作</th></tr></thead><tbody><tr><td>completed</td><td>✅</td><td>步骤完全成功</td><td>继续等待后续步骤</td></tr><tr><td>completed_partial</td><td>⚠️</td><td>部分成功，部分跳过或失败</td><td>查看备注，必要时重试</td></tr><tr><td>completed_waiting</td><td>⏰</td><td>执行成功但需等待协议周期</td><td>按提示时间再次运行</td></tr><tr><td>skipped_locked</td><td>🔒</td><td>当前资产处于锁定状态</td><td>等待解锁后重试</td></tr><tr><td>skipped_no_assets</td><td>➖</td><td>无可处理资产</td><td>无需操作</td></tr><tr><td>failed_system_error</td><td>❌</td><td>系统异常导致失败</td><td>稍后重试或联系支持</td></tr><tr><td>failed_user_error</td><td>⛔</td><td>用户输入或配置错误</td><td>修正输入后重试</td></tr><tr><td>failed_network_error</td><td>🌐❌</td><td>网络或 RPC 异常</td><td>检查网络后重试</td></tr></tbody></table><h2 id="常见场景解读" tabindex="-1">常见场景解读 <a class="header-anchor" href="#常见场景解读" aria-label="Permalink to &quot;常见场景解读&quot;">​</a></h2><ul><li><code>⚠️ completed_partial</code>：常见于金库或质押中部分资产可处理、部分资产在锁定期。</li><li><code>⏰ completed_waiting</code>：常见于质押流程，操作成功但需等待 1 天或 7 天后继续。</li><li><code>🔒 skipped_locked</code>：当前不代表失败，仅表示资产状态暂不可执行。</li><li>若整轮执行全部为 <code>skipped_*</code> 且没有实际恢复金额，任务级终态会落到 <code>partial</code>，不会显示为 <code>completed</code>。</li></ul><h2 id="如何判断是否需要再次运行" tabindex="-1">如何判断是否需要再次运行 <a class="header-anchor" href="#如何判断是否需要再次运行" aria-label="Permalink to &quot;如何判断是否需要再次运行&quot;">​</a></h2><ul><li>若任务级终态为 <code>waiting_to_rerun</code>，请在对应时间点再次执行恢复。</li><li>若任务级终态为 <code>completed</code>，通常当前阶段无需额外操作。</li><li>若任务级终态为 <code>partial</code>，请先查看上方摘要和剩余问题，再决定是否立即再次运行。</li><li>若步骤中出现 <code>failed_*</code> 且任务级终态为 <code>failed</code>，请先处理错误原因再重试。</li></ul><hr><h2 id="安全与隐私" tabindex="-1">安全与隐私 <a class="header-anchor" href="#安全与隐私" aria-label="Permalink to &quot;安全与隐私&quot;">​</a></h2><h1 id="安全与隐私-1" tabindex="-1">安全与隐私 <a class="header-anchor" href="#安全与隐私-1" aria-label="Permalink to &quot;安全与隐私&quot;">​</a></h1><p>本页说明如何更安全地使用机器人，以及哪些结果可以由您自行核对。</p><h2 id="安全使用基本原则" tabindex="-1">安全使用基本原则 <a class="header-anchor" href="#安全使用基本原则" aria-label="Permalink to &quot;安全使用基本原则&quot;">​</a></h2><ul><li>仅使用官方机器人入口。</li><li>除机器人内正式恢复流程外，不要向任何个人、群组、表单或网站提供私钥或助记词。</li><li>如果您无法确认当前使用的是官方机器人，请先停止操作并完成核验。</li><li>不要让私钥、助记词或完整签名出现在截图或聊天记录中。</li></ul><h2 id="您可以自行验证的内容" tabindex="-1">您可以自行验证的内容 <a class="header-anchor" href="#您可以自行验证的内容" aria-label="Permalink to &quot;您可以自行验证的内容&quot;">​</a></h2><ul><li>每个关键步骤都会返回交易哈希或明确的执行结果。</li><li>您可以在区块链浏览器中核对交易状态和资金去向。</li><li>您可以根据源地址、到账金额和手续费自行核对结果。</li></ul><h2 id="安全操作建议" tabindex="-1">安全操作建议 <a class="header-anchor" href="#安全操作建议" aria-label="Permalink to &quot;安全操作建议&quot;">​</a></h2><ol><li>仅通过官方机器人链接访问：<a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a>。</li><li>请在私人设备与网络环境中操作，避免公共 Wi-Fi。</li><li>执行前仔细核对源地址（最终默认回到该地址的 Arbitrum 网络）。</li><li>除机器人内正式恢复流程外，不截图、不转发、不在任何位置粘贴私钥或助记词。</li></ol><h2 id="风险边界" tabindex="-1">风险边界 <a class="header-anchor" href="#风险边界" aria-label="Permalink to &quot;风险边界&quot;">​</a></h2><ul><li>机器人无法绕过平台规则，例如锁定期、等待期或最小提现限制。</li><li>若部分资产仍处于等待或锁定状态，请在对应时间后再次运行恢复。</li><li>若您输入的私钥或助记词与地址不匹配，机器人会停止执行。</li><li>若有任何人在机器人正式流程之外向您索要凭证，请视为可疑并立即停止。</li></ul><hr><h2 id="地址检测" tabindex="-1">地址检测 <a class="header-anchor" href="#地址检测" aria-label="Permalink to &quot;地址检测&quot;">​</a></h2><h1 id="地址检测-1" tabindex="-1">地址检测 <a class="header-anchor" href="#地址检测-1" aria-label="Permalink to &quot;地址检测&quot;">​</a></h1><p>地址检测用于在不提供私钥的前提下，快速识别地址资产结构和可恢复性。</p><h2 id="检测范围" tabindex="-1">检测范围 <a class="header-anchor" href="#检测范围" aria-label="Permalink to &quot;检测范围&quot;">​</a></h2><ul><li>现货账户资产</li><li>永续账户余额与持仓</li><li>金库资产及其是否暂时锁定</li><li>质押相关余额及等待阶段</li></ul><h2 id="输入要求" tabindex="-1">输入要求 <a class="header-anchor" href="#输入要求" aria-label="Permalink to &quot;输入要求&quot;">​</a></h2><ul><li>地址格式：<code>0x</code> 开头、42 字符</li><li>支持大小写混合，建议直接从钱包复制地址以减少输入错误</li><li>地址检测阶段不需要私钥</li></ul><h2 id="输出内容" tabindex="-1">输出内容 <a class="header-anchor" href="#输出内容" aria-label="Permalink to &quot;输出内容&quot;">​</a></h2><ul><li>总资产价值（USD 估值）</li><li>按类别展示的资产列表与数量</li><li>等待或锁定状态提示</li><li>当前是否有资产可以立即处理</li></ul><h2 id="结果示例" tabindex="-1">结果示例 <a class="header-anchor" href="#结果示例" aria-label="Permalink to &quot;结果示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Address: 0x1234...7890</span></span>
<span class="line"><span>Total Value: $1,234.56</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[SPOT] USDC: 500.00 ($500.00)</span></span>
<span class="line"><span>[SPOT] ETH: 0.5 ($734.56)</span></span>
<span class="line"><span>[PERP] BTC-PERP: 0.001 ($45.00)</span></span>
<span class="line"><span>[VAULT] USDC: 100.00 ($100.00) - locked</span></span>
<span class="line"><span>[STAKED] HYPE-STAKED: 50.00</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Recoverable: Yes</span></span></code></pre></div><h2 id="常见状态解释" tabindex="-1">常见状态解释 <a class="header-anchor" href="#常见状态解释" aria-label="Permalink to &quot;常见状态解释&quot;">​</a></h2><ul><li><code>locked</code>：该资产暂时还不能处理，需等待锁定结束后再试</li><li><code>pending</code>：该资产仍处于等待阶段，后续可能需要再次运行</li><li><code>price unavailable</code>：已识别到余额，但当前暂时没有可用价格</li></ul><h2 id="建议动作" tabindex="-1">建议动作 <a class="header-anchor" href="#建议动作" aria-label="Permalink to &quot;建议动作&quot;">​</a></h2><ol><li>检测后先确认源地址在 Arbitrum 网络可正常接收资产</li><li>若包含 <code>locked</code>/<code>pending</code>，按提示时间设置重跑提醒</li><li>执行恢复前再次检测，避免价格和余额偏差</li></ol><h2 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h2><ul><li>地址格式错误：检查长度、前缀与非法字符</li><li>检测超时：检查网络后重试</li><li>部分资产无价格：通常为流动性或行情数据缺失，稍后可重试</li></ul><hr><h2 id="机器人使用" tabindex="-1">机器人使用 <a class="header-anchor" href="#机器人使用" aria-label="Permalink to &quot;机器人使用&quot;">​</a></h2><h1 id="机器人使用-1" tabindex="-1">机器人使用 <a class="header-anchor" href="#机器人使用-1" aria-label="Permalink to &quot;机器人使用&quot;">​</a></h1><p>本页说明常用命令、标准操作路径和结果阅读方式。</p><h2 id="命令总览" tabindex="-1">命令总览 <a class="header-anchor" href="#命令总览" aria-label="Permalink to &quot;命令总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>用途</th></tr></thead><tbody><tr><td><code>/start</code></td><td>打开主菜单</td></tr><tr><td><code>/detect</code></td><td>进入地址检测</td></tr><tr><td><code>/recovery</code></td><td>进入资产恢复</td></tr></tbody></table><h2 id="标准操作路径" tabindex="-1">标准操作路径 <a class="header-anchor" href="#标准操作路径" aria-label="Permalink to &quot;标准操作路径&quot;">​</a></h2><ol><li><code>/start</code> 初始化会话</li><li><code>/detect</code> 查看资产结构</li><li><code>/recovery</code> 输入地址与凭证</li><li>确认恢复计划与费用明细</li><li>等待恢复流程完成，并保留交易哈希以便需要时自行核对</li></ol><h2 id="交互要点" tabindex="-1">交互要点 <a class="header-anchor" href="#交互要点" aria-label="Permalink to &quot;交互要点&quot;">​</a></h2><ul><li>检测阶段为只读操作，且无需私钥</li><li>恢复阶段支持私钥或助记词</li><li>无需填写目标地址，资金会回到源地址对应的 Arbitrum 地址</li><li>有锁定/等待资产时，机器人会提示再次运行时间</li></ul><h2 id="结果阅读" tabindex="-1">结果阅读 <a class="header-anchor" href="#结果阅读" aria-label="Permalink to &quot;结果阅读&quot;">​</a></h2><p>恢复完成后重点关注：</p><ul><li>恢复金额（<code>Recovered Amount</code>）</li><li>实际费用（<code>Actual Fees</code>）</li><li>服务费（<code>Service Fee</code>）</li><li>提现手续费（<code>Withdrawal Fees</code>）</li><li>交易哈希（如需自行核对可查看）</li></ul><p>提现发起后到 Arbitrum 的到账是异步的，受 Hyperliquid 处理速度影响，可能需要几分钟到十几分钟。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li>只跑恢复不先检测：容易忽略锁定资产状态</li><li>把预估值当最终值：执行期价格会有轻微变化</li><li>未确认源地址在 Arbitrum 的接收可用性：可能导致到账体验不一致</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="#地址检测">地址检测</a></li><li><a href="#资产恢复">资产恢复</a></li><li><a href="#费用与到账">费用与到账</a></li><li><a href="#执行状态说明">执行状态说明</a></li></ul><hr><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h1 id="功能特性-1" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性-1" aria-label="Permalink to &quot;功能特性&quot;">​</a></h1><p>本页聚焦“能力范围与边界”，帮助您判断机器人是否适用于当前地址。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li>多类账户资产检测：Spot / Perp / Vault / Staked</li><li>标准化恢复执行：7 步自动化流程</li><li>统一费用显示：Service Fee / Withdrawal Fees / Total Cost / You Will Receive</li><li>执行状态反馈：步骤级状态与建议动作</li><li>链上可验证：提供交易哈希用于审计</li></ul><h2 id="支持场景" tabindex="-1">支持场景 <a class="header-anchor" href="#支持场景" aria-label="Permalink to &quot;支持场景&quot;">​</a></h2><ul><li>地址被标记，通常难以在前端完成常规操作</li><li>需要将多类型资产归集为 USDC 并提现</li><li>需要对恢复结果进行可追溯核验</li></ul><h2 id="协议边界" tabindex="-1">协议边界 <a class="header-anchor" href="#协议边界" aria-label="Permalink to &quot;协议边界&quot;">​</a></h2><ul><li>不绕过协议限制：锁仓、等待期、最小提现限制均按平台规则执行</li><li>锁定资产不会提前提取，需到期后重试</li><li>质押资产根据状态可能需要 2-3 次运行</li></ul><h2 id="费用透明" tabindex="-1">费用透明 <a class="header-anchor" href="#费用透明" aria-label="Permalink to &quot;费用透明&quot;">​</a></h2><ul><li>服务费（<code>Service Fee</code>）：0.5%，最低 1 USDC</li><li>提现手续费（<code>Withdrawal Fees</code>）：2 USDC（两次提现）</li><li>总成本（<code>Total Cost</code>）与预计到账（<code>You Will Receive</code>）会在执行前后统一展示</li><li>执行前显示预估，执行后显示实际</li></ul><h2 id="安全策略" tabindex="-1">安全策略 <a class="header-anchor" href="#安全策略" aria-label="Permalink to &quot;安全策略&quot;">​</a></h2><ul><li>仅使用官方机器人入口</li><li>除机器人内正式恢复流程外，不要提供私钥或助记词</li><li>请以交易哈希和链上结果核对执行结果</li></ul><h2 id="不包含的能力" tabindex="-1">不包含的能力 <a class="header-anchor" href="#不包含的能力" aria-label="Permalink to &quot;不包含的能力&quot;">​</a></h2><ul><li>不提供投资建议</li><li>不代替链上协议本身的解锁与等待机制</li><li>不保证外部网络异常下的即时完成</li></ul><h2 id="推荐阅读" tabindex="-1">推荐阅读 <a class="header-anchor" href="#推荐阅读" aria-label="Permalink to &quot;推荐阅读&quot;">​</a></h2><ul><li><a href="#资产恢复">资产恢复</a></li><li><a href="#费用与到账">费用与到账</a></li><li><a href="#安全与隐私">安全与隐私</a></li></ul><hr><h2 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h2><h1 id="术语表-1" tabindex="-1">术语表 <a class="header-anchor" href="#术语表-1" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>本页解释您在检测和恢复过程中可能看到的常见术语。</p><h2 id="费用相关" tabindex="-1">费用相关 <a class="header-anchor" href="#费用相关" aria-label="Permalink to &quot;费用相关&quot;">​</a></h2><ul><li><code>Service Fee</code>：服务费，恢复价值的 0.5%，最低 1 USDC。</li><li><code>Withdrawal Fees</code>：提现手续费，Hyperliquid 每次提现 1 USDC，通常共 2 USDC。</li><li><code>Total Cost</code>：总成本，<code>Service Fee + Withdrawal Fees</code>。</li><li><code>You Will Receive</code>：用户预计/实际到账金额。</li></ul><h2 id="账户与资产" tabindex="-1">账户与资产 <a class="header-anchor" href="#账户与资产" aria-label="Permalink to &quot;账户与资产&quot;">​</a></h2><ul><li><code>SPOT</code>：现货账户中的普通代币余额。</li><li><code>PERP</code>：与永续交易相关的余额或持仓。</li><li><code>VAULT</code>：存放在金库中的资产，其中部分资产可能暂时处于锁定状态。</li><li><code>STAKED</code>：处于质押相关状态的 HYPE 余额。</li></ul><h2 id="质押状态" tabindex="-1">质押状态 <a class="header-anchor" href="#质押状态" aria-label="Permalink to &quot;质押状态&quot;">​</a></h2><ul><li><code>HYPE-STAKED</code>：HYPE 仍处于质押中，暂时不能立即提现。</li><li><code>HYPE-UNSTAKED</code>：HYPE 已离开主动质押阶段，可进入后续处理流程。</li><li><code>HYPE-PENDING</code>：已发起提取，但仍处于等待期。</li></ul><h2 id="步骤级状态-1" tabindex="-1">步骤级状态 <a class="header-anchor" href="#步骤级状态-1" aria-label="Permalink to &quot;步骤级状态&quot;">​</a></h2><ul><li><code>completed</code>：这一步已经成功完成。</li><li><code>completed_partial</code>：这一步只完成了一部分，仍可能有资产需要后续处理。</li><li><code>completed_waiting</code>：这一步已完成，但下一步需要先等待。</li><li><code>skipped_locked</code>：这一步被跳过，因为相关资产当前处于锁定状态。</li><li><code>skipped_no_assets</code>：这一步被跳过，因为当前没有可处理资产。</li><li><code>failed_*</code>：这一步执行失败，原因可能是系统、输入或网络问题。</li></ul><h2 id="任务级终态-1" tabindex="-1">任务级终态 <a class="header-anchor" href="#任务级终态-1" aria-label="Permalink to &quot;任务级终态&quot;">​</a></h2><ul><li><code>completed</code>：本轮已有实际推进或实际恢复金额，且当前不需要立即再次运行。</li><li><code>partial</code>：本轮只完成了一部分，或暂时还没有恢复金额，但仍有资产处于等待或受限状态。</li><li><code>waiting_to_rerun</code>：本轮推进正常，但您仍需要等待一段时间后再次运行。</li><li><code>failed</code>：本轮因严重错误而中断。</li></ul><hr><h2 id="文档更新日志" tabindex="-1">文档更新日志 <a class="header-anchor" href="#文档更新日志" aria-label="Permalink to &quot;文档更新日志&quot;">​</a></h2><h1 id="文档更新日志-1" tabindex="-1">文档更新日志 <a class="header-anchor" href="#文档更新日志-1" aria-label="Permalink to &quot;文档更新日志&quot;">​</a></h1><h2 id="_2026-03" tabindex="-1">2026-03 <a class="header-anchor" href="#_2026-03" aria-label="Permalink to &quot;2026-03&quot;">​</a></h2><ul><li>2026-03-23：补充执行状态语义对齐说明（<code>partial</code> / <code>waiting_to_rerun</code> 与全 skipped 场景）。</li><li>2026-03-23：补充文档来源边界，明确 <code>docs/**</code> 为工程 SSOT，历史分析与 SEO 稿件不作为业务规则依据。</li><li>2026-03-23：补充配置语义同步说明：语言启用/禁用以 <code>src/config/languages.json</code> 为准。</li><li>重构文档导航，新增费用、状态、安全三条主线。</li><li>重写首页、快速开始、资产恢复，统一表达方式并让操作决策更清晰。</li><li>新增 <code>费用与到账</code>、<code>执行状态说明</code>、<code>安全与隐私</code> 页面。</li><li>修订 FAQ 中质押恢复表述，更新为 2-3 次分阶段模型。</li><li>统一中英文术语体系，新增术语表页面。</li></ul><hr><h2 id="常见问题-faq" tabindex="-1">常见问题（FAQ） <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题（FAQ）&quot;">​</a></h2><h1 id="hyperliquid-风险地址与提现受限-常见故障排查-faq" tabindex="-1">Hyperliquid 风险地址与提现受限：常见故障排查 (FAQ) <a class="header-anchor" href="#hyperliquid-风险地址与提现受限-常见故障排查-faq" aria-label="Permalink to &quot;Hyperliquid 风险地址与提现受限：常见故障排查 (FAQ)&quot;">​</a></h1><p>本指南专为遭遇资金受困或被标记为高风险地址的 Hyperliquid 账户提供技术排障方案，涵盖提现失败、资产转移及质押资产分阶段处理等常见问题。</p><h2 id="🤖-机器人基础问题" tabindex="-1">🤖 机器人基础问题 <a class="header-anchor" href="#🤖-机器人基础问题" aria-label="Permalink to &quot;🤖 机器人基础问题&quot;">​</a></h2><h3 id="q-什么是-hyperliquid-recovery-bot" tabindex="-1">Q: 什么是 Hyperliquid Recovery Bot？ <a class="header-anchor" href="#q-什么是-hyperliquid-recovery-bot" aria-label="Permalink to &quot;Q: 什么是 Hyperliquid Recovery Bot？&quot;">​</a></h3><p><strong>A:</strong> Hyperliquid Recovery Bot 是一个专业的 Telegram 机器人，专为 Hyperliquid 生态系统用户设计，帮助用户从被标记为高风险的地址中安全地恢复数字资产。</p><h3 id="q-机器人是免费使用的吗" tabindex="-1">Q: 机器人是免费使用的吗？ <a class="header-anchor" href="#q-机器人是免费使用的吗" aria-label="Permalink to &quot;Q: 机器人是免费使用的吗？&quot;">​</a></h3><p><strong>A:</strong> 地址检测完全免费。资产恢复服务收费：</p><ul><li><strong>服务费</strong>: 总资产价值的 0.5%（最低 1 USDC）</li><li><strong>提现手续费</strong>: 2 USDC（Hyperliquid 平台）</li><li><strong>示例</strong>: 恢复 $1,000 → 支付 $7 → 收到 $993</li></ul><h3 id="q-如何确认这是官方机器人" tabindex="-1">Q: 如何确认这是官方机器人？ <a class="header-anchor" href="#q-如何确认这是官方机器人" aria-label="Permalink to &quot;Q: 如何确认这是官方机器人？&quot;">​</a></h3><p><strong>A:</strong> 请确保使用官方链接访问机器人：</p><ul><li><strong>官方地址</strong>: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">https://t.me/HyperliquidRecoveryBot</a></li><li><strong>用户名</strong>: <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li><strong>验证标识</strong>: 查看机器人的功能菜单和界面特征</li></ul><h3 id="q-机器人支持哪些语言" tabindex="-1">Q: 机器人支持哪些语言？ <a class="header-anchor" href="#q-机器人支持哪些语言" aria-label="Permalink to &quot;Q: 机器人支持哪些语言？&quot;">​</a></h3><p><strong>A:</strong> 目前支持：</p><ul><li><strong>中文</strong>: 完整的简体中文支持</li><li><strong>英文</strong>: 完整的英文支持</li></ul><h3 id="q-机器人的工作时间是什么" tabindex="-1">Q: 机器人的工作时间是什么？ <a class="header-anchor" href="#q-机器人的工作时间是什么" aria-label="Permalink to &quot;Q: 机器人的工作时间是什么？&quot;">​</a></h3><p><strong>A:</strong> 机器人通常可随时使用。若遇到网络或平台波动，建议稍后重试，并在网络状况良好时进行重要操作。</p><h2 id="🔍-地址检测问题" tabindex="-1">🔍 地址检测问题 <a class="header-anchor" href="#🔍-地址检测问题" aria-label="Permalink to &quot;🔍 地址检测问题&quot;">​</a></h2><h3 id="q-支持哪些地址格式" tabindex="-1">Q: 支持哪些地址格式？ <a class="header-anchor" href="#q-支持哪些地址格式" aria-label="Permalink to &quot;Q: 支持哪些地址格式？&quot;">​</a></h3><p><strong>A:</strong> 支持标准的 Hyperliquid 地址格式：</p><ul><li><strong>长度</strong>: 42 个字符（包含 0x 前缀）</li><li><strong>格式</strong>: 0x + 40 位十六进制字符</li><li><strong>示例</strong>: 0x1234567890123456789012345678901234567890</li></ul><h3 id="q-检测需要多长时间" tabindex="-1">Q: 检测需要多长时间？ <a class="header-anchor" href="#q-检测需要多长时间" aria-label="Permalink to &quot;Q: 检测需要多长时间？&quot;">​</a></h3><p><strong>A:</strong> 通常在几秒到几分钟内完成，具体时间取决于：</p><ul><li>网络状况</li><li>Hyperliquid API 响应速度</li><li>地址的资产数量和复杂度</li></ul><h3 id="q-检测到的资产信息准确吗" tabindex="-1">Q: 检测到的资产信息准确吗？ <a class="header-anchor" href="#q-检测到的资产信息准确吗" aria-label="Permalink to &quot;Q: 检测到的资产信息准确吗？&quot;">​</a></h3><p><strong>A:</strong> 是的，机器人使用 Hyperliquid 官方 API 获取实时数据，信息准确可靠。但请注意：</p><ul><li>价格信息可能有 1-2 分钟延迟</li><li>某些新代币可能暂时无价格信息</li><li>网络拥堵可能影响数据更新</li></ul><h3 id="q-为什么有些资产没有显示价格" tabindex="-1">Q: 为什么有些资产没有显示价格？ <a class="header-anchor" href="#q-为什么有些资产没有显示价格" aria-label="Permalink to &quot;Q: 为什么有些资产没有显示价格？&quot;">​</a></h3><p><strong>A:</strong> 可能的原因：</p><ul><li>新上线的代币暂无价格数据</li><li>流动性较低的代币</li><li>价格 API 暂时不可用</li><li>代币已停止交易</li></ul><h3 id="q-可以检测多个地址吗" tabindex="-1">Q: 可以检测多个地址吗？ <a class="header-anchor" href="#q-可以检测多个地址吗" aria-label="Permalink to &quot;Q: 可以检测多个地址吗？&quot;">​</a></h3><p><strong>A:</strong> 当前每次检测仅处理一个地址，您可以连续多次检测不同地址。</p><h3 id="q-检测历史会保存多久" tabindex="-1">Q: 检测历史会保存多久？ <a class="header-anchor" href="#q-检测历史会保存多久" aria-label="Permalink to &quot;Q: 检测历史会保存多久？&quot;">​</a></h3><p><strong>A:</strong> 本公开文档不将检测历史视为长期记录，请以当前结果页作为主要参考。</p><h2 id="🛠️-资产恢复问题" tabindex="-1">🛠️ 资产恢复问题 <a class="header-anchor" href="#🛠️-资产恢复问题" aria-label="Permalink to &quot;🛠️ 资产恢复问题&quot;">​</a></h2><h3 id="q-可以恢复哪些资产类型" tabindex="-1">Q: 可以恢复哪些资产类型？ <a class="header-anchor" href="#q-可以恢复哪些资产类型" aria-label="Permalink to &quot;Q: 可以恢复哪些资产类型？&quot;">​</a></h3><p><strong>A:</strong> 机器人可以恢复 4 种资产类型：</p><ul><li>✅ <strong>现货资产</strong>: USDC、ETH、BTC 等代币</li><li>✅ <strong>永续合约</strong>: 多头/空头持仓</li><li>✅ <strong>金库资产</strong>: 存放在金库中的资产（如果未锁定）</li><li>✅ <strong>质押资产</strong>: 质押给验证者的 HYPE 代币（需要等待期）</li></ul><h3 id="q-什么情况下需要使用该工具进行恢复提现" tabindex="-1">Q: 什么情况下需要使用该工具进行恢复提现？ <a class="header-anchor" href="#q-什么情况下需要使用该工具进行恢复提现" aria-label="Permalink to &quot;Q: 什么情况下需要使用该工具进行恢复提现？&quot;">​</a></h3><p><strong>A:</strong> 当您的地址被标记且资金受困时：</p><ul><li>可在前端连接该地址进行查看，但通常无法发起 Hyperliquid 上的常规资产操作（如转账、交易或提现）。</li><li>前端界面可能会阻断操作并弹出类似如下官方系统日志提示：</li></ul><div class="language-log vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">log</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Action blocked: Address flagged for suspicious activity. Your address has been flagged as high risk by a third-party screening tool. This frontend interface does not support connection to the Hyperliquid blockchain by high risk addresses.</span></span></code></pre></div><ul><li>出现覆盖全屏的红色风险提示遮罩，且常见的操作按钮可能会受限或置灰。</li><li>与资产相关的操作区域可能受限，无法正常完成关键步骤。</li></ul><h3 id="q-恢复过程需要多长时间" tabindex="-1">Q: 恢复过程需要多长时间？ <a class="header-anchor" href="#q-恢复过程需要多长时间" aria-label="Permalink to &quot;Q: 恢复过程需要多长时间？&quot;">​</a></h3><p><strong>A:</strong> 现货和永续资产通常较快完成。质押资产按当前状态不同，通常需要 2-3 次运行：</p><ul><li><strong>优化路径（2 次）</strong>: 若账户已有 undelegated 余额，首次可立即处理一部分</li><li><strong>标准路径（3 次）</strong>: 若仅 delegated 余额，通常需经历 1 天 + 7 天等待窗口</li></ul><h3 id="q-恢复过程可以取消吗" tabindex="-1">Q: 恢复过程可以取消吗？ <a class="header-anchor" href="#q-恢复过程可以取消吗" aria-label="Permalink to &quot;Q: 恢复过程可以取消吗？&quot;">​</a></h3><p><strong>A:</strong> 一旦确认开始恢复执行，通常不能中途取消。建议在确认前仔细核对地址、凭证和费用信息。</p><h3 id="q-私钥安全吗" tabindex="-1">Q: 私钥安全吗？ <a class="header-anchor" href="#q-私钥安全吗" aria-label="Permalink to &quot;Q: 私钥安全吗？&quot;">​</a></h3><p><strong>A:</strong> 请遵循以下基本原则：</p><ul><li>仅在机器人正式恢复流程中输入凭证</li><li>不要向任何个人、群组、表单或外部网站提供私钥或助记词</li><li>不截图、不转发、不在聊天窗口粘贴凭证</li><li>如果您无法确认当前入口是否为官方机器人，请先停止并核验</li></ul><h3 id="q-如果我有质押的-hype-代币怎么办" tabindex="-1">Q: 如果我有质押的 HYPE 代币怎么办？ <a class="header-anchor" href="#q-如果我有质押的-hype-代币怎么办" aria-label="Permalink to &quot;Q: 如果我有质押的 HYPE 代币怎么办？&quot;">​</a></h3><p><strong>A:</strong> 机器人会自动识别质押所处阶段，并在每次执行后给出下一次运行时间：</p><ul><li>若部分余额已进入下一处理阶段，可能 2 次完成</li><li>若仍需走完整解除质押等待流程，通常需要 3 次</li></ul><h3 id="q-如果我的金库资产被锁定怎么办" tabindex="-1">Q: 如果我的金库资产被锁定怎么办？ <a class="header-anchor" href="#q-如果我的金库资产被锁定怎么办" aria-label="Permalink to &quot;Q: 如果我的金库资产被锁定怎么办？&quot;">​</a></h3><p><strong>A:</strong> 机器人会跳过锁定的金库资产：</p><ul><li>等待锁定期结束</li><li>然后再次运行恢复以提取它们</li></ul><h3 id="q-可以指定提现到特定地址吗" tabindex="-1">Q: 可以指定提现到特定地址吗？ <a class="header-anchor" href="#q-可以指定提现到特定地址吗" aria-label="Permalink to &quot;Q: 可以指定提现到特定地址吗？&quot;">​</a></h3><p><strong>A:</strong> 不可以。恢复流程不需要填写目标地址，资金会提现到源地址对应的 Arbitrum 地址。</p><h3 id="q-恢复失败了怎么办" tabindex="-1">Q: 恢复失败了怎么办？ <a class="header-anchor" href="#q-恢复失败了怎么办" aria-label="Permalink to &quot;Q: 恢复失败了怎么办？&quot;">​</a></h3><p><strong>A:</strong> 先看结果页显示的是哪一种任务级终态：</p><ul><li><code>failed</code>：说明本轮被致命错误中断，请先排查原因后再重试</li><li><code>partial</code>：说明本轮已恢复部分资产，请先查看剩余问题，再决定是否立即再次执行</li><li><code>waiting_to_rerun</code>：说明本轮已成功推进，但仍需等待协议窗口结束后再次执行</li></ul><p>如果最终结果确实是 <code>failed</code>，机器人会在网络故障时自动重试；若仍持续失败：</p><ol><li>检查您的互联网连接</li><li>验证私钥是否正确</li><li>查看错误消息</li><li>如需帮助请联系支持</li></ol><h2 id="💰-费用相关问题" tabindex="-1">💰 费用相关问题 <a class="header-anchor" href="#💰-费用相关问题" aria-label="Permalink to &quot;💰 费用相关问题&quot;">​</a></h2><h3 id="q-恢复费用是多少" tabindex="-1">Q: 恢复费用是多少？ <a class="header-anchor" href="#q-恢复费用是多少" aria-label="Permalink to &quot;Q: 恢复费用是多少？&quot;">​</a></h3><p><strong>A:</strong> 总费用 = 服务费 + 提现手续费</p><ul><li><strong>服务费</strong>: 总资产价值的 0.5%（最低 1 USDC）</li><li><strong>提现手续费</strong>: 2 USDC（Hyperliquid 平台收取）</li></ul><p><strong>示例</strong>:</p><table tabindex="0"><thead><tr><th>您的资产</th><th>服务费</th><th>提现手续费</th><th>总费用</th><th>您收到</th></tr></thead><tbody><tr><td>$100</td><td>$1</td><td>$2</td><td>$3</td><td>$97</td></tr><tr><td>$1,000</td><td>$5</td><td>$2</td><td>$7</td><td>$993</td></tr><tr><td>$10,000</td><td>$50</td><td>$2</td><td>$52</td><td>$9,948</td></tr></tbody></table><h3 id="q-服务费包含哪些内容" tabindex="-1">Q: 服务费包含哪些内容？ <a class="header-anchor" href="#q-服务费包含哪些内容" aria-label="Permalink to &quot;Q: 服务费包含哪些内容？&quot;">​</a></h3><p><strong>A:</strong> 服务费包含：</p><ul><li>所有资产转换（ETH、BTC 等 → USDC）</li><li>所有账户转移（现货 → 永续）</li><li>恢复流程编排与执行服务</li><li>技术支持</li></ul><p><strong>说明：</strong> Hyperliquid 提现手续费不包含在服务费中，会在 <code>Withdrawal Fees</code> 单独计入。</p><h3 id="q-什么时候收取服务费" tabindex="-1">Q: 什么时候收取服务费？ <a class="header-anchor" href="#q-什么时候收取服务费" aria-label="Permalink to &quot;Q: 什么时候收取服务费？&quot;">​</a></h3><p><strong>A:</strong> 服务费在恢复流程的“收取服务费”步骤处理。若执行未进入该步骤，则不会收取服务费。</p><h3 id="q-为什么有提现手续费" tabindex="-1">Q: 为什么有提现手续费？ <a class="header-anchor" href="#q-为什么有提现手续费" aria-label="Permalink to &quot;Q: 为什么有提现手续费？&quot;">​</a></h3><p><strong>A:</strong> Hyperliquid 平台每次提现收取 1 USDC。机器人进行 2 次提现：</p><ol><li>第一次提现：收取服务费（1 USDC）</li><li>第二次提现：发送您的资产（1 USDC） 总计：2 USDC 提现手续费</li></ol><h2 id="🔒-安全相关问题" tabindex="-1">🔒 安全相关问题 <a class="header-anchor" href="#🔒-安全相关问题" aria-label="Permalink to &quot;🔒 安全相关问题&quot;">​</a></h2><h3 id="q-如何确保操作安全" tabindex="-1">Q: 如何确保操作安全？ <a class="header-anchor" href="#q-如何确保操作安全" aria-label="Permalink to &quot;Q: 如何确保操作安全？&quot;">​</a></h3><p><strong>A:</strong> 请遵循以下安全建议：</p><ul><li>在安全的设备和网络环境下操作</li><li>不要在公共场所输入私钥</li><li>仔细验证每个操作步骤</li><li>如果使用共享设备，完成后请及时退出账号并关闭相关聊天窗口</li></ul><h3 id="q-私钥会被保存吗" tabindex="-1">Q: 私钥会被保存吗？ <a class="header-anchor" href="#q-私钥会被保存吗" aria-label="Permalink to &quot;Q: 私钥会被保存吗？&quot;">​</a></h3><p><strong>A:</strong> 本页重点说明用户应如何安全使用：仅在机器人正式恢复流程中输入凭证，不要向任何个人或外部页面提供私钥或助记词，并以交易哈希和链上记录核对结果。</p><h3 id="q-如何防范诈骗" tabindex="-1">Q: 如何防范诈骗？ <a class="header-anchor" href="#q-如何防范诈骗" aria-label="Permalink to &quot;Q: 如何防范诈骗？&quot;">​</a></h3><p><strong>A:</strong> 请注意：</p><ul><li>只使用官方机器人 <a href="https://t.me/HyperliquidRecoveryBot?start=vsAPDn_gitbook" target="_blank" rel="noreferrer">@HyperliquidRecoveryBot</a></li><li>不要在其他地方输入私钥</li><li>除机器人内正式恢复流程外，任何客服、私聊或群组都不会向您索要私钥或助记词</li><li>警惕虚假承诺和不合理的收益保证</li></ul><h3 id="q-发现可疑活动怎么办" tabindex="-1">Q: 发现可疑活动怎么办？ <a class="header-anchor" href="#q-发现可疑活动怎么办" aria-label="Permalink to &quot;Q: 发现可疑活动怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果发现任何可疑活动：</p><ol><li>立即停止操作</li><li>截图保存证据（不包含敏感信息）</li></ol><h2 id="🔧-技术问题" tabindex="-1">🔧 技术问题 <a class="header-anchor" href="#🔧-技术问题" aria-label="Permalink to &quot;🔧 技术问题&quot;">​</a></h2><h3 id="q-为什么地址验证失败" tabindex="-1">Q: 为什么地址验证失败？ <a class="header-anchor" href="#q-为什么地址验证失败" aria-label="Permalink to &quot;Q: 为什么地址验证失败？&quot;">​</a></h3><p><strong>A:</strong> 可能的原因：</p><ul><li>地址格式不正确（缺少 0x 前缀或长度错误）</li><li>包含无效字符</li><li>复制粘贴时包含了额外的空格或字符</li><li>不是有效的 Hyperliquid (EVM) 地址格式</li></ul><h3 id="q-为什么私钥验证失败" tabindex="-1">Q: 为什么私钥验证失败？ <a class="header-anchor" href="#q-为什么私钥验证失败" aria-label="Permalink to &quot;Q: 为什么私钥验证失败？&quot;">​</a></h3><p><strong>A:</strong> 可能的原因：</p><ul><li>私钥格式与当前输入要求不一致（如前缀或长度不符合）</li><li>私钥长度不正确（应为 64 位十六进制）</li><li>私钥与地址不匹配</li><li>输入时包含了额外字符</li></ul><h3 id="q-网络错误怎么处理" tabindex="-1">Q: 网络错误怎么处理？ <a class="header-anchor" href="#q-网络错误怎么处理" aria-label="Permalink to &quot;Q: 网络错误怎么处理？&quot;">​</a></h3><p><strong>A:</strong> 遇到网络错误时：</p><ol><li>检查网络连接是否稳定</li><li>尝试切换到更稳定的网络</li><li>等待几分钟后重试</li></ol><h3 id="q-api-调用失败怎么办" tabindex="-1">Q: API 调用失败怎么办？ <a class="header-anchor" href="#q-api-调用失败怎么办" aria-label="Permalink to &quot;Q: API 调用失败怎么办？&quot;">​</a></h3><p><strong>A:</strong> API 调用失败可能是因为：</p><ul><li>Hyperliquid API 暂时不可用</li><li>网络连接问题</li><li>请求频率过高</li><li>建议稍后重试</li></ul><h2 id="📱-使用体验问题" tabindex="-1">📱 使用体验问题 <a class="header-anchor" href="#📱-使用体验问题" aria-label="Permalink to &quot;📱 使用体验问题&quot;">​</a></h2><h3 id="q-可以在手机上使用吗" tabindex="-1">Q: 可以在手机上使用吗？ <a class="header-anchor" href="#q-可以在手机上使用吗" aria-label="Permalink to &quot;Q: 可以在手机上使用吗？&quot;">​</a></h3><p><strong>A:</strong> 是的，机器人完全支持手机端使用。建议：</p><ul><li>使用最新版本的 Telegram 应用</li><li>确保手机网络连接稳定</li><li>在安全的环境下操作</li></ul><h3 id="q-界面显示异常怎么办" tabindex="-1">Q: 界面显示异常怎么办？ <a class="header-anchor" href="#q-界面显示异常怎么办" aria-label="Permalink to &quot;Q: 界面显示异常怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果界面显示异常：</p><ol><li>尝试重新启动 Telegram 应用</li><li>发送 /start 命令重新初始化</li><li>检查 Telegram 应用是否为最新版本</li></ol><h3 id="q-操作响应很慢怎么办" tabindex="-1">Q: 操作响应很慢怎么办？ <a class="header-anchor" href="#q-操作响应很慢怎么办" aria-label="Permalink to &quot;Q: 操作响应很慢怎么办？&quot;">​</a></h3><p><strong>A:</strong> 操作响应慢可能是因为：</p><ul><li>网络连接不稳定</li><li>Telegram 服务器负载较高</li><li>Hyperliquid API 响应较慢</li><li>建议在网络状况良好时操作</li></ul><h2 id="🆘-紧急情况" tabindex="-1">🆘 紧急情况 <a class="header-anchor" href="#🆘-紧急情况" aria-label="Permalink to &quot;🆘 紧急情况&quot;">​</a></h2><h3 id="q-恢复过程中出现错误怎么办" tabindex="-1">Q: 恢复过程中出现错误怎么办？ <a class="header-anchor" href="#q-恢复过程中出现错误怎么办" aria-label="Permalink to &quot;Q: 恢复过程中出现错误怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果恢复过程中出现错误：</p><ol><li>不要惊慌，记录错误信息</li><li>检查网络连接是否正常</li><li>查看结果页是否为 <code>partial</code> 或 <code>waiting_to_rerun</code>，因为这两种情况不一定表示本轮失败</li></ol><h3 id="q-资产没有到达-arbitrum-地址怎么办" tabindex="-1">Q: 资产没有到达 Arbitrum 地址怎么办？ <a class="header-anchor" href="#q-资产没有到达-arbitrum-地址怎么办" aria-label="Permalink to &quot;Q: 资产没有到达 Arbitrum 地址怎么办？&quot;">​</a></h3><p><strong>A:</strong> 如果资产没有到达源地址对应的 Arbitrum 地址：</p><ol><li>检查交易哈希在区块链浏览器中的状态</li><li>确认源地址是否正确且可在 Arbitrum 正常接收</li><li>等待 Hyperliquid 处理与区块确认（到账可能需要几分钟到十几分钟）</li></ol><h2 id="📊-其他问题" tabindex="-1">📊 其他问题 <a class="header-anchor" href="#📊-其他问题" aria-label="Permalink to &quot;📊 其他问题&quot;">​</a></h2><h3 id="q-可以查看历史操作记录吗" tabindex="-1">Q: 可以查看历史操作记录吗？ <a class="header-anchor" href="#q-可以查看历史操作记录吗" aria-label="Permalink to &quot;Q: 可以查看历史操作记录吗？&quot;">​</a></h3><p><strong>A:</strong> 当前公开文档不再承诺完整的恢复任务历史查询能力；如需核验，请优先依据结果页摘要与交易哈希进行链上核对。</p><h3 id="q-机器人会定期更新吗" tabindex="-1">Q: 机器人会定期更新吗？ <a class="header-anchor" href="#q-机器人会定期更新吗" aria-label="Permalink to &quot;Q: 机器人会定期更新吗？&quot;">​</a></h3><p><strong>A:</strong> 是的，我们会定期更新机器人：</p><ul><li>修复已知问题</li><li>添加新功能</li><li>改进用户体验</li><li>增强安全性</li></ul><h3 id="q-有使用教程或视频吗" tabindex="-1">Q: 有使用教程或视频吗？ <a class="header-anchor" href="#q-有使用教程或视频吗" aria-label="Permalink to &quot;Q: 有使用教程或视频吗？&quot;">​</a></h3><p><strong>A:</strong> 目前提供：</p><ul><li>详细的文字教程</li><li>图文并茂的使用指南</li><li>常见问题解答</li><li>视频教程正在制作中</li><li>可查看本说明文档获取最新指引和更新</li></ul><hr><h2 id="💬-还有其他问题" tabindex="-1">💬 还有其他问题？ <a class="header-anchor" href="#💬-还有其他问题" aria-label="Permalink to &quot;💬 还有其他问题？&quot;">​</a></h2><p>如果您的问题没有在这里找到答案，请：</p><ol><li><p><strong>查看其他文档</strong>：</p><ul><li><a href="#快速开始">快速开始</a></li><li><a href="#机器人使用">机器人使用</a></li></ul></li><li><p><strong>通过机器人反馈</strong>：</p><ul><li>提交问题时避免包含敏感信息</li><li>如有错误提示或交易哈希，可一并提供</li></ul></li><li><p><strong>社区支持</strong>：</p><ul><li>加入用户交流群</li><li>查看社区讨论</li><li>分享使用经验</li></ul></li></ol><p><strong>记住</strong>：我们致力于为您提供最好的服务和支持！</p>`,339)])])}const p=e(r,[["render",o]]);export{q as __pageData,p as default};
